            query='SELECT serial_number AS "Serial",\n       substr(report_time, 1, 16) AS "Date",\n       conflict_type AS "Conflict type",\n       event_type AS "Event type",\n       species_h AS "Species responsible",\n       COALESCE(json_extract(event_details, \'$."Livestock species"\'), \'\') AS "Livestock species",\n       CAST(COALESCE(CAST(json_extract(event_details, \'$."Total livestock dead"\') AS REAL), 0) AS INTEGER) AS "Livestock killed",\n       CAST(COALESCE(CAST(json_extract(event_details, \'$."Total livestock injured"\') AS REAL), 0) AS INTEGER) AS "Livestock injured",\n       COALESCE(json_extract(event_details, \'$."Animals found inside or outside boma"\'),\n                json_extract(event_details, \'$."Animals found"\'), \'\') AS "Attack location",\n       COALESCE(json_extract(event_details, \'$."Type of crop"\'), \'\') AS "Crop",\n       COALESCE(json_extract(event_details, \'$."Type of Property"\'), \'\') AS "Property",\n       COALESCE(json_extract(event_details, \'$."Extent of damage"\'), \'\') AS "Extent of damage",\n       COALESCE(json_extract(event_details, \'$."Age"\'), \'\') AS "Age",\n       COALESCE(json_extract(event_details, \'$."Sex"\'), \'\') AS "Sex",\n       COALESCE(CAST(json_extract(event_details, \'$."Action"\') AS TEXT),\n                CAST(json_extract(event_details, \'$."Action taken"\') AS TEXT),\n                CAST(json_extract(event_details, \'$."Action Taken"\') AS TEXT), \'\') AS "Action taken",\n       geometry AS "Location"\nFROM df WHERE is_conflict = 1\nORDER BY report_time\n',
